n = int(input())
words = input().split()
counts = {}
for word in words:
    counts[word] = counts.get(word, 0) + 1
items = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
for word, count in items[:n]:
    print(word, count)

a, b = map(int, input().split())

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

primes = [n for n in range(a, b + 1) if is_prime(n)]
print(" ".join(str(n) for n in primes))
print(f"个数={len(primes)}")

n = int(input())
students = []
for _ in range(n):
    name, score = input().split()
    students.append((name, int(score)))

students.sort(key=lambda item: (-item[1], item[0]))
for name, score in students:
    rank = 1 + sum(1 for _, other in students if other > score)
    print(rank, name, score)

ranges = {"优秀": 0, "良好": 0, "及格": 0, "不及格": 0}
for _, score in students:
    if score >= 90:
        ranges["优秀"] += 1
    elif score >= 80:
        ranges["良好"] += 1
    elif score >= 60:
        ranges["及格"] += 1
    else:
        ranges["不及格"] += 1

for label, count in ranges.items():
    print(f"{label}={count}")
